        onSuccess={() => {
          fetchAllData();
          toast({
            title: editingDozent ? 'Gespeichert' : 'Erstellt',
            description: editingDozent ? 'Dozent wurde aktualisiert.' : 'Neuer Dozent wurde erstellt.'
          });
        }}
