                        <div className="flex items-center gap-2">
                          <Badge
                            variant={a.fields.bezahlt ? 'default' : 'outline'}
                            className={a.fields.bezahlt ? 'bg-accent text-accent-foreground' : 'border-destructive text-destructive'}
