            <Label htmlFor="gebaeude">Gebäude</Label>
            <Input
              id="gebaeude"
              value={formData.gebaeude}
              onChange={(e) => setFormData(prev => ({ ...prev, gebaeude: e.target.value }))}
            />
          </div>
          <div className="space-y-2">
            <Label htmlFor="kapazitaet">Kapazität</Label>
